<?php
declare(strict_types=1);
require_once __DIR__.'/../src/Service/CatalogRepository.php';
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$error='';try{$catalog=(new CatalogRepository())->load(__DIR__.'/../dataset/products.json',__DIR__.'/../dataset/categories.json',__DIR__.'/../dataset/class_requirements.csv');}catch(Throwable $x){http_response_code(500);$error=$x->getMessage();$catalog=new CatalogService([],[],[]);}
$f=['q'=>trim((string)($_GET['q']??'')),'category'=>(string)($_GET['category']??''),'min'=>trim((string)($_GET['min']??'')),'max'=>trim((string)($_GET['max']??'')),'active'=>isset($_GET['active'])];$errors=[];
foreach(['min','max'] as $k)if($f[$k]!==''&&(!is_numeric($f[$k])||(float)$f[$k]<0)){$errors[]='Цена должна быть неотрицательным числом.';$f[$k]='';}
if($f['min']!==''&&$f['max']!==''&&(float)$f['min']>(float)$f['max'])$errors[]='Минимальная цена не может превышать максимальную.';
$items=$errors===[]?$catalog->products($f):[];
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Каталог — ТРПО 05</title><link rel="stylesheet" href="/assets/styles.css"></head><body>
<header class="site-header"><div class="brand">TRPO / Практическая №05</div><div class="tag">PHP · ООП · JSON</div></header><nav class="site-nav"><a href="#overview">Обзор</a><a href="#filters">Фильтры</a><a href="#catalog">Каталог</a><a href="#model">Модель</a></nav>
<main class="wrap"><section class="hero" id="overview"><div class="eyebrow">Технологии разработки программного обеспечения</div><h1>Каталог товаров</h1><p class="muted">Объектная модель товаров и категорий, загрузка JSON и фильтрация отдельно от HTML.</p><strong>Солопов Антон · ЭПБО-01-25</strong></section>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php foreach($errors as $x):?><div class="notice error"><?=e($x)?></div><?php endforeach;?>
<div class="cards"><article class="card"><div class="muted">Всего товаров</div><div class="metric"><?=count($catalog->products())?></div></article><article class="card"><div class="muted">Активных товаров</div><div class="metric"><?=$catalog->countActive()?></div></article><article class="card"><div class="muted">Средняя цена</div><div class="metric"><?=e(number_format($catalog->averagePrice(),2,',',' '))?> ₽</div></article></div>
<section class="panel" id="filters"><div class="eyebrow">GET · Параметры каталога</div><h2>Фильтрация</h2><form method="get" class="form-grid"><div class="field"><label for="q">Название</label><input id="q" name="q" value="<?=e($f['q'])?>" placeholder="Например, Товар 4"></div><div class="field"><label for="category">Категория</label><select id="category" name="category"><option value="">Все категории</option><?php foreach($catalog->categories() as $c):?><option value="<?=$c->id()?>" <?=$f['category']===(string)$c->id()?'selected':''?>><?=e($c->name())?></option><?php endforeach;?></select></div><div class="field"><label for="min">Цена от</label><input id="min" name="min" type="number" min="0" step="0.01" value="<?=e($f['min'])?>"></div><div class="field"><label for="max">Цена до</label><input id="max" name="max" type="number" min="0" step="0.01" value="<?=e($f['max'])?>"></div><div class="field"><label><input type="checkbox" name="active" value="1" <?=$f['active']?'checked':''?>> Только активные</label></div><div><button>Применить</button> <a class="btn ghost" href="/">Сбросить</a></div></form></section>
<section class="panel" id="catalog"><div class="eyebrow">Объекты Product</div><h2>Результаты каталога</h2><p class="muted">Найдено товаров: <?=count($items)?></p><div class="cards"><?php foreach($items as $p):?><article class="card"><span class="pill"><?=$p->isActive()?'Активен':'Неактивен'?></span><h3><?=e($p->name())?></h3><p class="muted"><?=e($catalog->categoryName($p->categoryId()))?></p><div class="metric"><?=e($p->formattedPrice())?></div><small class="muted">ID <?=$p->id()?> · категория #<?=$p->categoryId()?></small></article><?php endforeach;?></div><?php if(!$items):?><div class="empty">Товары не найдены.</div><?php endif;?></section>
<section class="panel" id="model"><div class="eyebrow">Использование dataset</div><h2>Требования к классам</h2><p>class_requirements.csv прочитан репозиторием и используется для вывода свойств моделей.</p><div class="table-wrap"><table class="table"><thead><tr><th>Класс</th><th>Свойство</th><th>Тип</th><th>Обязательное</th></tr></thead><tbody><?php foreach($catalog->requirements() as $r):?><tr><td><?=e($r['class']??'')?></td><td><?=e($r['property']??'')?></td><td><?=e($r['type']??'')?></td><td><?=e($r['required']??'')?></td></tr><?php endforeach;?></tbody></table></div></section></main><footer class="site-footer">Практическая работа №05 · PHP · ООП</footer></body></html>
